/* ExploraSelf Leadership Compass. Local-first: no visitor data is transmitted. */
'use strict';
const C=Compass,KEY='exploraself-compass-v1',BEFORE_DEMO=KEY+'-before-demo';
let state=C.blank(),page='overview',domain='self',saveTimer,toastTimer;
try{const stored=localStorage.getItem(KEY);if(stored)state=C.sanitize(JSON.parse(stored));}catch(_){/* A restricted browser can still use the tool without persistence. */}
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stage=()=>C.stages.find(s=>s.id===state.stage),money=n=>n===null||!Number.isFinite(n)?'—':(C.estimatedKeys(state).length?'≈ ':'')+new Intl.NumberFormat('en-US',{style:'currency',currency:state.profile.currency,maximumFractionDigits:0}).format(n),pct=n=>n===null||!Number.isFinite(n)?'—':(C.estimatedKeys(state).length?'≈ ':'')+(n*100).toFixed(1)+'%',decimal=(n,suffix='')=>n===null||!Number.isFinite(n)?'—':(C.estimatedKeys(state).length?'≈ ':'')+new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n)+suffix;
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='○ Saved on this browser';}catch(_){$('#save-status').textContent='○ Session only · download a backup';}},180);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function download(name,body,type='text/plain'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const stageDrawing=id=>{const shapes={building:'<circle cx="30" cy="24" r="9"/><path d="M14 60v-8c0-12 32-12 32 0v8M55 25h22v29H55zM61 34h10M61 41h6"/>',growing:'<path d="M14 61h65M22 56V44h12v12M44 56V33h12v23M66 56V20h12v36M19 33l24-13 14 3 19-14M66 9h10v10"/>',scaling:'<circle cx="46" cy="21" r="8"/><circle cx="20" cy="32" r="6"/><circle cx="72" cy="32" r="6"/><path d="M31 58V46c0-12 30-12 30 0v12M8 59v-9c0-9 15-10 21-4M63 45c6-5 21-4 21 5v9M36 64h20"/>',leading:'<circle cx="46" cy="17" r="8"/><circle cx="18" cy="56" r="7"/><circle cx="46" cy="56" r="7"/><circle cx="74" cy="56" r="7"/><path d="M46 25v15M18 49v-9h56v9M46 40v9M36 17l6 5 13-14"/>'};return `<svg viewBox="0 0 92 76" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[id]}</svg>`;};
function journey(){const current=stage();return `<div class="journey" aria-label="Choose your business stage">${C.stages.map((st,i)=>`<button data-stage="${st.id}" class="${st.id===state.stage?'active':''}" aria-pressed="${st.id===state.stage}"><span class="step">0${i+1}${st.id===state.stage?'<span class="stage-dot"></span>':''}</span><span class="stage-icon">${stageDrawing(st.id)}</span><b>${st.name}</b><small>${st.role}</small></button>`).join('')}</div><section class="stage-explainer" aria-label="${current.name} explained"><div class="stage-story"><p class="eyebrow">${current.name.toUpperCase()} · DOES THIS SOUND LIKE YOU?</p><h3>${current.daily}</h3><p>${current.line}</p><p class="stage-promise">Leave this stage with a dated record in each domain, a written decision, a scheduled action and a review date.</p></div><div class="stage-map"><ol>${current.map.map((text,i)=>`<li><span>${i+1}</span><b>${text}</b>${i<2?'<i aria-hidden="true">→</i>':''}</li>`).join('')}</ol><p>${current.next}</p></div></section>`;}
function levels(){return `<div class="level-tabs"><a class="${page==='clarity'?'active':''}" href="#clarity">01 · Get clear</a><a class="${page==='numbers'?'active':''}" href="#numbers">02 · See your numbers</a><a class="${page==='plan'?'active':''}" href="#plan">03 · Choose your next steps</a></div>`;}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function demoStrip(){return state.demo?'<div class="demo-strip"><span>ILLUSTRATIVE EXAMPLE · These imported entries were labelled as a fictional example. Replace them with your own records before using a result.</span><button class="text-button" data-exit-demo>Return to my workspace ×</button></div>':'';}
function compassArt(){return `<div class="compass-art" aria-hidden="true"><svg viewBox="0 0 330 320"><g fill="none" stroke="var(--gold)"><circle cx="165" cy="157" r="107" opacity=".3"/><circle cx="165" cy="157" r="81" opacity=".15"/><circle cx="165" cy="157" r="129" opacity=".12" stroke-dasharray="2 8"/><path d="M165 29v255M37 157h256" opacity=".2"/><path d="M165 58 231 157 165 256 99 157Z" opacity=".4"/><path d="M165 75 196 157 165 234 134 157Z" fill="var(--gold)" fill-opacity=".09" stroke-width="1.5"/><path d="m165 75 0 82 31 0M165 234v-77h-31" opacity=".8"/><circle cx="165" cy="157" r="16" fill="var(--deep)"/><circle cx="165" cy="157" r="5" fill="var(--gold)"/></g><g font-family="Libre Franklin,Arial" font-size="9" letter-spacing="2" fill="var(--gold-hi)" text-anchor="middle"><text x="165" y="16">SELF</text><text x="165" y="309">WORK</text><text x="32" y="147" font-size="7" letter-spacing=".5">PEOPLE</text><text x="297" y="147" font-size="7" letter-spacing=".5">MARKET</text></g><g fill="var(--gold-hi)"><circle cx="165" cy="50" r="3"/><circle cx="272" cy="157" r="3"/><circle cx="165" cy="264" r="3"/><circle cx="58" cy="157" r="3"/></g></svg></div>`;}
function overview(){const s=C.summary(state),c=C.calculate(state.numbers,state.scenario,state.moneyRanges),focus=C.actions(state,c)[0],started=s.answered>0,all=Object.values(state.answers).length;return `${demoStrip()}<div class="intro"><div><p class="eyebrow">YOUR BUSINESS. YOUR LIFE. YOUR NEXT CHAPTER.</p><h1>${state.profile.name?'Welcome, '+esc(state.profile.name)+'.':'From founder to'}${state.profile.name?'<br><em>Let’s see the whole picture.</em>':'<br><em>intentional leader.</em>'}</h1><p class="lede">For solopreneurs and small businesses. Understand where you are, see what needs your attention, and build your next move with clarity.</p></div>${badge('THE EXPLORASELF WAY')}</div><section class="hero"><div class="hero-copy"><p class="eyebrow">${started?'CONTINUE YOUR EXPLORATION':'YOUR STARTING POINT'}</p><h2>A stronger business<br>starts with a <em>clearer you.</em></h2><p>Numbers reveal what is happening. Personal leadership helps you decide what to do about it. Bring both into focus.</p><div class="actions"><a class="primary" href="#clarity">${started?'Continue my assessment':'Find my starting point'} <span>↗</span></a></div></div>${compassArt()}</section><div class="section-row"><h2>Where are you building from?</h2><p>Choose your current stage.<br>You can explore every stage.</p></div>${journey()}<div class="section-row"><h2>Four domains. One whole you.</h2><p>${s.answered}/8 responses in ${stage().name.toLowerCase()} · ${all}/32 overall</p></div><div class="domain-grid">${s.scores.map(d=>`<a class="card domain-card domain-${d.id}" href="#clarity" data-domain="${d.id}"><div class="domain-icon domain-${d.id}">${d.icon}</div><div class="micro">${d.full}</div><h3>${d.name}</h3><p>${d.description}</p><div class="meter"><i style="width:${d.score??0}%"></i></div><div class="score-row"><span>${d.answered===d.total?'Self-rating':'Not yet complete'}</span><span>${d.answered===d.total?d.score+'%':d.answered+'/'+d.total+' answered'} ↗</span></div></a>`).join('')}</div><div class="bottom-grid"><div class="card focus-card"><div class="num">↗</div><div><p class="eyebrow">ONE USEFUL NEXT STEP</p><h3>${esc(focus.title)}</h3><p>${esc(focus.text)}</p><a class="text-button" href="#plan">See my next moves →</a></div></div><div class="mini-stats"><div class="mini-stat"><small>LEFT AFTER BUSINESS COSTS</small><b>${money(c.operating)}</b><p>Monthly money left before loan interest, tax and depreciation</p></div><div class="mini-stat"><small>MONTHS OF BILLS SAVED</small><b>${decimal(c.buffer,' mo')}</b><p>Available cash divided by one month of payments</p></div></div></div><div class="flow-note"><i></i><span>Clarity before momentum. Evidence before the next commitment.</span><i></i></div><p class="hint">Your progress stays in this browser. No assessment account is required. These are reflection prompts and planning calculations—not a psychological test or a certified stage rating.</p>`;}
const answerLabels=[['Not yet','I need to work on this.'],['I think so','I have not checked it yet.'],['Mostly','I have real examples.'],['Yes, I’ve checked','I can show what happened.']];
function clarity(){const s=C.summary(state),d=C.domains.find(d=>d.id===domain),qs=s.questions.filter(q=>q.domain===domain);return `${demoStrip()}<div class="intro"><div><p class="eyebrow">LEVEL 01 / GET CLEAR</p><h1>What is true <em>today?</em></h1><p class="lede">Choose what sounds like you today. Add a short example, or tell us what you still need to find out. You do not need business jargon to get started.</p></div>${badge(s.answered+'/8 ANSWERED')}</div>${levels()}${journey()}<div class="level-tabs" aria-label="Assessment domain">${C.domains.map(x=>`<a href="#clarity" data-domain="${x.id}" class="${domain===x.id?'active':''}">${x.name} <span aria-hidden="true">${x.id===domain?'↗':''}</span></a>`).join('')}</div><div class="assessment-heading"><div class="domain-icon domain-${d.id}">${d.icon}</div><div><p class="eyebrow">${d.full} / ${stage().name}</p><h3>${d.lens}</h3><p>${stage().line}</p></div></div>${qs.map((q,i)=>`<section class="card question"><div class="question-top"><span class="qnum">0${C.domains.indexOf(d)*2+i+1}</span><div><h3>${q.text}</h3><p class="context">${q.prompt}</p></div></div><div class="answers" role="group" aria-label="Response to ${esc(q.text)}">${answerLabels.map((a,k)=>`<button class="answer ${state.answers[q.id]===k?'selected':''}" data-answer="${q.id}" data-value="${k}" aria-pressed="${state.answers[q.id]===k}"><b>${a[0]}</b>${a[1]}</button>`).join('')}</div><label for="evidence-${q.id}">What happened in real life?<textarea id="evidence-${q.id}" data-evidence="${q.id}" maxlength="1500" placeholder="For example: last month I tried… and the result was…">${esc(state.evidence[q.id]||'')}</textarea></label><p class="hint">Not sure? That is a useful starting point. Your example helps you choose what to work on next.</p></section>`).join('')}<div class="sticky-actions"><p class="hint">${s.answered}/8 responses · ${s.scores.reduce((sum,d)=>sum+d.evidenced,0)}/8 notes added<br>Saved as you go.</p><div class="actions">${domain!=='self'?'<button class="secondary" data-prev-domain>← Back</button>':''}${domain==='market'?'<a class="primary" href="#numbers">Bring in the numbers →</a>':'<button class="primary" data-next-domain>Next domain →</button>'}</div></div>`;}
const rawMoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:state.profile.currency,maximumFractionDigits:0}).format(n);
function bandLabel(b){return b.low===0&&b.high===0?rawMoney(0)+' · none':b.high===null?rawMoney(b.low)+'+':b.low===0?'Under '+rawMoney(b.high):rawMoney(b.low)+'–'+rawMoney(b.high);}
function rangeNote(f){const band=C.bandsFor(f.key).find(b=>b.id===state.moneyRanges?.[f.key]);if(state.legacyAmounts?.[f.key]!==undefined)return 'Your older backup stored '+rawMoney(state.legacyAmounts[f.key])+'. Check it against your record, then enter the amount you choose. It is preserved but is not used in calculations until you enter it.';if(!band)return '';if(band.high===null)return 'Above '+rawMoney(band.low)+'? Add your best estimate below so we can calculate.';if(band.high===band.low)return 'Using '+rawMoney(band.low)+'.';return 'Enter your own approximate amount within this range. We never choose a number for you.';}
function rangeFieldInner(f){const id=state.moneyRanges?.[f.key],band=C.bandsFor(f.key).find(b=>b.id===id),selected=id==='exact'?'exact':band?id:state.numbers[f.key]!==''?'exact':'unknown',showExact=selected==='exact'||(band&&band.high!==band.low);return `<label for="r-${f.key}">${f.label}<span class="unit">${state.profile.currency} · ${f.unit}</span></label><select id="r-${f.key}" data-money-range="${f.key}" aria-describedby="help-${f.key} range-note-${f.key}"><option value="unknown" ${selected==='unknown'?'selected':''}>Choose a range · or leave unknown</option>${C.bandsFor(f.key).map(b=>`<option value="${b.id}" ${selected===b.id?'selected':''}>${bandLabel(b)}</option>`).join('')}<option value="exact" ${selected==='exact'?'selected':''}>Enter an exact amount</option></select><div class="exact-entry" ${showExact?'':'hidden'}><label for="n-${f.key}">${band?'Your approximate amount':'Your amount'}<input id="n-${f.key}" type="number" inputmode="decimal" min="${band?band.low:0}" step="any" ${band&&band.high!==null?'max="'+band.high+'"':''} data-number="${f.key}" value="${esc(state.numbers[f.key])}" placeholder="Enter your own amount" aria-describedby="help-${f.key}"></label></div><small id="range-note-${f.key}" class="range-note">${rangeNote(f)}</small><small id="help-${f.key}">${f.help}</small>`;}
function inputField(f){if(C.moneyKeys.includes(f.key))return `<div class="field" id="field-${f.key}">${rangeFieldInner(f)}</div>`;return `<div class="field"><label for="n-${f.key}">${f.label} <span class="unit">${f.unit}</span><input id="n-${f.key}" type="number" inputmode="decimal" min="0" ${f.key==='founderDependency'?'max="100"':''} step="${['orders','newCustomers','leads'].includes(f.key)?'1':'any'}" data-number="${f.key}" value="${esc(state.numbers[f.key])}" placeholder="Not sure yet" aria-describedby="help-${f.key}"></label><small id="help-${f.key}">${f.help}</small></div>`;}
function estimateNotice(){const keys=C.estimatedKeys(state),pending=C.moneyKeys.filter(key=>{const b=C.bandsFor(key).find(b=>b.id===state.moneyRanges?.[key]);return b&&b.high!==b.low&&state.numbers[key]==='';});return (state.needsAmountReview?'<div class="notice">Imported range amounts are preserved. Confirm them against your own records; older backups may contain automatically chosen amounts.</div>':'')+(keys.length?`<div class="notice estimate-notice"><b>Using your approximate amounts.</b> You entered ${keys.length} approximate amount${keys.length===1?'':'s'}. Results use those amounts, not an automatically chosen middle of a range.</div>`:'')+(pending.length?`<div class="notice">${pending.length} selected range${pending.length===1?' needs':'s need'} your own amount before we can calculate. Zero is only used when you choose zero.</div>`:'');}
function moneyMap(c){if(c.n.revenue===null||c.n.revenue<=0||c.n.variable===null||c.n.acquisition===null||c.n.fixed===null||c.errors.length)return '';const parts=[{label:'Delivery',v:c.n.variable,cls:'delivery'},{label:'Getting customers',v:c.n.acquisition,cls:'selling'},{label:'Running costs',v:c.n.fixed,cls:'running'},{label:'Left over',v:Math.max(0,c.operating),cls:'left'}],total=Math.max(c.n.revenue,c.n.variable+c.n.acquisition+c.n.fixed);return `<div class="money-map"><p class="eyebrow">WHERE YOUR SALES MONEY GOES</p><div class="money-track" role="img" aria-label="${parts.map(x=>x.label+': '+rawMoney(x.v)).join('. ')}${c.operating<0?'. Costs exceed sales.':''}">${parts.map(x=>`<span class="${x.cls}" style="width:${x.v/total*100}%"></span>`).join('')}</div><div class="money-key">${parts.map(x=>`<span><i class="${x.cls}"></i>${x.label}</span>`).join('')}</div><p class="hint">${c.operating<0?'Costs are '+rawMoney(-c.operating)+' higher than sales.':'From each '+rawMoney(100)+' sold, about '+rawMoney(c.operating/c.n.revenue*100)+' is left after these costs.'} ${C.estimatedKeys(state).length?'Based on range estimates.':''}</p></div>`;}
function metric(title,value,note,kind=''){const decision=title.includes('customer')||title.includes('Customer')?'Open the matching customer records. Which customer or channel will you follow up?':title.includes('hour')||title.includes('time')?'Open your calendar. Which task will you stop, change or hand over?':title.includes('cash')||title.includes('Cash')||title.includes('bills')||title.includes('money out')?'Open your bank statement and payment dates. Which payment or collection needs action?':'Open the related sales and cost entries. Which price, cost or commitment will you change?';return `<div class="metric"><div><strong>${title}</strong><small>${note}</small><small class="metric-decision">${decision}</small></div><b class="${kind}">${value}</b></div>`;}
function numberResults(){const c=C.calculate(state.numbers,state.scenario,state.moneyRanges),n=c.n;return `<p class="eyebrow">YOUR MONTHLY PICTURE</p><h3>Here is the picture.</h3><p class="hint">A machine can do this arithmetic. Only you can choose which price, promise, payment or working habit changes next.</p>${estimateNotice()}${moneyMap(c)}${c.errors.length?'<div class="validation" role="alert">'+c.errors.map(esc).join('<br>')+'</div>':''}${metric('Left after delivery & getting customers',money(c.contribution),'Your sales minus the cost of doing the work and getting customers. Regular running costs come next.',c.contribution===null?'':c.contribution<0?'negative':'positive')}${metric('Share left after delivery & selling',pct(c.contributionRate),'The percentage of sales left after delivery and customer-getting costs.')}${metric('Left after business costs',money(c.operating),'What is left after the costs you entered. Before loan interest, tax and depreciation.',c.operating===null?'':c.operating<0?'negative':'positive')}${metric('Left after allowing for your unpaid time',money(c.economic),'Take off a fair allowance for hours you worked without a wage. This helps you plan; it is not an extra bill you paid.',c.economic===null?'':c.economic<0?'negative':'positive')}${metric('Sales needed to cover running costs',money(c.breakEven),'The sales you need if your mix of products, prices and costs stays the same.')}${metric('What you spent per new customer',money(c.cac),'This month’s customer-getting spending divided by new paying customers. Some spending may lead to sales later.')}${metric('Money left per hour you worked',money(c.hourReturn),'Money left after business costs divided by your work hours. This is not your take-home wage.')}${metric('How much of your available time you used',pct(c.capacity),'Your actual hours compared with the hours you said you can comfortably work.',c.capacity!==null&&c.capacity>1?'negative':'')}${metric('Money in minus money out',money(c.cashFlow),'Actual customer payments received minus every payment made. New loans or investment are not included.',c.cashFlow===null?'':c.cashFlow<0?'negative':'positive')}${metric('How long your savings cover bills',decimal(c.buffer,' mo'),'Months of current bills your available cash would cover if no more money arrived.')}${metric('How long cash lasts at this monthly loss',c.cashFlow!==null&&c.cashFlow>=0?'Cash is not shrinking':decimal(c.runway,' mo'),'If money is going out faster than it comes in, this is how long today’s cash could last at that pace.')}${metric('Extra cash to reach your savings goal',money(c.bufferGap),'The extra amount needed to hold your chosen number of months of bills.')}${metric('Enquiries compared with new customers',pct(c.conversion),'New customers divided by serious enquiries this month. They may be different people if buying takes longer.')}${metric('Sales from returning customers',pct(c.repeatShare),'The part of this month’s sales from people who had bought before. It does not tell us how many stayed.')}${metric('Sales from your biggest customer',pct(c.concentration),'How much of your sales depends on just one customer.')}<p class="hint" style="margin-top:18px">“—” means we need more information or the calculation is not possible. Leave unknowns blank; enter zero only when the amount really is zero.</p>${n.newCustomers!==null&&n.leads!==null&&n.newCustomers>n.leads?'<div class="notice warn" style="margin-top:15px">You have more new customers than enquiries this month. Some may have enquired earlier or come from another source. Check before drawing a conclusion.</div>':''}${c.contribution!==null&&c.contribution<=0?'<div class="notice warn" style="margin-top:15px">Sales are not yet covering delivery and customer-getting costs. Selling more at the same price and costs will not fix that gap.</div>':''}`;}
function scenarioResults(){const c=C.calculate(state.numbers,state.scenario,state.moneyRanges);if(!c.scenario)return '<div class="notice">Add sales, finished orders, delivery costs, customer-getting spending and running costs to try a what-if. Check any conflicting answers first.</div>';return `<div class="compare"><div class="mini-stat"><small>SALES IN THIS WHAT-IF</small><b>${money(c.scenario.revenue)}</b><p>${decimal(c.scenario.orders)} modeled orders</p></div><div class="mini-stat"><small>MONEY LEFT AFTER BUSINESS COSTS</small><b class="${c.scenario.operating<0?'negative':'positive'}">${money(c.scenario.operating)}</b><p>Before loan interest, tax and depreciation</p></div><div class="mini-stat"><small>CHANGE FROM TODAY</small><b class="${c.scenario.delta<0?'negative':'positive'}">${money(c.scenario.delta)}</b><p>Monthly change if these choices hold</p></div></div>`;}
function numbers(){const sections=[['economics','01','Your sales & costs','Pick one month and use it throughout. Count each cost only once. You can choose a range or enter an exact amount.'],['founder','02','Your time & energy','How much work goes into this? Count your time, including the hours you do without a wage.'],['cash','03','Money in the bank','What actually arrived and went out? A sale is not money in the bank until the customer pays.'],['market','04','Your customers','Think about this same month. Who was interested, who bought and who came back?']];return `${demoStrip()}<div class="intro"><div><p class="eyebrow">LEVEL 02 / SEE YOUR NUMBERS</p><h1>Make the numbers <em>mean something.</em></h1><p class="lede">Choose a range, then enter your own approximate amount. Copy an exact amount when you have it. Leave unknowns blank.</p></div>${badge(state.profile.currency+' · MONTHLY INPUTS')}</div>${levels()}<div class="numbers-guide"><span>① Choose one month</span><i>→</i><span>② Pick ranges or exact amounts</span><i>→</i><span>③ See what is left</span></div><div class="number-layout"><div>${sections.map(([id,num,title,desc])=>`<section class="card input-section"><p class="eyebrow">${num} / YOUR INPUTS</p><h3>${title}</h3><p class="hint">${desc}</p><div class="fields">${C.fields.filter(f=>f.section===id).map(inputField).join('')}</div></section>`).join('')}<section class="card"><label for="data-note">Where did these numbers come from?<textarea id="data-note" data-note="data" maxlength="2000" placeholder="For example: last month’s bank statement. Sales are exact; costs are my best guess.">${esc(state.notes.data||'')}</textarea></label><p class="hint" style="margin-top:9px">If some products leave much more money than others, check them separately too. These totals give you a starting picture.</p></section></div><aside class="card result-panel" id="number-results" aria-label="Calculated business results">${numberResults()}</aside></div><section class="card scenario"><p class="eyebrow">THE WHAT-IF LAB</p><h2>Test a decision before you make it.</h2><p class="lede">What happens if you change your price, sell more orders or make each order cheaper to deliver? Move the sliders to explore.</p><div class="sliders">${[['price','Price change',-50,50],['volume','More or fewer orders',-50,100],['cost','Lower delivery cost per order',0,50]].map(([key,label,min,max])=>`<label for="s-${key}">${label}<output id="o-${key}">${state.scenario[key]>0?'+':''}${state.scenario[key]}%</output><input id="s-${key}" type="range" min="${min}" max="${max}" step="1" value="${state.scenario[key]}" data-scenario="${key}"></label>`).join('')}</div><div id="scenario-results">${scenarioResults()}</div><div id="scenario-estimates">${estimateNotice()}</div><p class="hint" style="margin-top:18px">This what-if changes your price, number of orders and delivery cost per order. Marketing spending and regular running costs stay the same. A higher price might change demand; more orders might need extra help. This model does not predict those changes or the money in your bank. Check them before acting.</p></section><div class="sticky-actions"><p class="hint">Calculations update as you type.<br>All amounts in ${state.profile.currency}.</p><a class="primary" href="#plan">Turn insight into next steps →</a></div>`;}
function checkpoint(c,s){const required=['revenue','variable','acquisition','fixed','cash','cashIn','cashOut','reserveMonths','hours','availableHours'];const missing=required.filter(k=>C.num(state.numbers[k])===null);const checks=[{ok:s.ready,text:s.ready?'All eight answers are “Mostly” or “Yes, I’ve checked”, with a real-life note.':`${s.missing.length} answer${s.missing.length===1?' needs':'s need'} more checking or a short real-life example.`},{ok:missing.length===0&&!c.errors.length,text:missing.length?`${missing.length} key money or time answers are still unknown.`:c.errors.length?'Some answers do not fit together.':'Your key money and time answers are filled in.'},{ok:c.contribution!==null&&c.contribution>0,text:c.contribution!==null&&c.contribution>0?'Sales cover the cost of delivering the work and getting customers.':'We have not yet shown that sales cover delivery and customer-getting costs.'},{ok:c.buffer!==null&&c.n.reserveMonths!==null&&c.buffer>=c.n.reserveMonths,text:c.buffer!==null&&c.n.reserveMonths!==null?`How long your savings cover bills: ${decimal(c.buffer)} months against your ${decimal(c.n.reserveMonths)}-month target.`:'How long your savings cover bills and your chosen target still need to be compared.'},{ok:c.capacity!==null&&c.capacity<=1,text:c.capacity!==null?`Your work hours versus your limit: ${pct(c.capacity)} of your chosen sustainable hours.`:'We still need to check your work hours against your chosen limit.'}];if(C.estimatedKeys(state).length)checks.push({ok:false,text:'Your ranges are a useful start. Confirm the important amounts before making a bigger commitment.'});return {checks,covered:checks.every(x=>x.ok)};}
const strategicPrompts={
 building:{self:['A business that supports the life I want.','Try one week within the working hours I chose.','Hours worked, time to rest and progress toward my income goal.'],people:['People who support me and tell me the truth.','Agree one boundary and ask someone what I may be missing.','One clear agreement and one useful challenge to my idea.'],work:['An offer that leaves money after the work is done.','Work out the cost and try one small paid job.','Money left per job and the hours I actually worked.'],market:['A problem customers are willing to pay to solve.','Ask customers about the problem and try a small paid offer.','What customers told me, who paid and the result they got.']},
 growing:{self:['A rhythm that creates progress without consuming my life.','Remove one low-value recurring task for two weeks.','Founder hours against sustainable capacity.'],people:['Clearer agreements and fewer difficult surprises.','Use a clearer scope and change agreement on the next project.','Extra work, repeated mistakes and how well we work together.'],work:['Regular sales that leave enough money and time.','Check costs, customer payments and work hours every week.','Money left after delivery and selling costs, bank balance and hours worked.'],market:['A way to bring in the right customers more regularly.','Track one acquisition channel and interview lost customers.','Spending per new customer and money left after delivery and selling costs.']},
 scaling:{self:['People can make good decisions without waiting for me.','Let someone else make one decision within clear limits.','Decisions completed without founder rescue.'],people:['People know their job and have the skills and trust to do it.','Agree who decides in five common situations.','How often people need my help, how decisions went and what they learned.'],work:['More work delivered well, with enough money to pay for it.','Try one small increase in help. Include set-up costs and a slower-sales case.','Money left after costs, lowest bank balance and customer results during the test.'],market:['Customers can find and buy from us without depending on one person or platform.','Try one new way to find customers, with a clear spending limit.','Money left after costs and customer results compared with the usual offer.']},
 leading:{self:['A goal that is worth the time and energy it needs.','Check whether one commitment still serves what matters to me.','Time freed up and what changed in the things I care about.'],people:['People who can lead when I am absent.','Practise how someone else would take over if I were away.','Decisions others handled and problems we fixed in the handover.'],work:['Money and time going to the things that matter most.','Compare three ways to use the same money or time. Test one protection against a problem.','What we could lose, what we give up and what actually happened.'],market:['A business that helps people and takes responsibility for its effects.','Review one customer, team and wider-impact outcome.','Real results, unwanted effects and what we changed.']}
};
function strategyCanvas(c,s){const saved=state.strategy[state.stage]||{},personal=[...s.scores].filter(x=>['self','people'].includes(x.id)).sort((a,b)=>(b.weak.length-a.weak.length))[0],business=[...s.scores].filter(x=>['work','market'].includes(x.id)).sort((a,b)=>(b.weak.length-a.weak.length))[0];let direction='Check what you know before taking the next big step.';if(c.errors.length)direction='Check the answers that do not fit before making a money decision.';else if(c.contribution!==null&&c.contribution<=0)direction='Make sure each sale leaves money before trying to sell more.';else if(c.cashFlow!==null&&c.cashFlow<0)direction='Understand the cash gap and protect near-term choices.';else if(c.capacity!==null&&c.capacity>1)direction='Make the work fit your available hours before taking on more.';else if(c.operating!==null)direction={building:'Test a paid offer within the time and money you can afford to risk.',growing:'Repeat what brings good customers and leaves enough money and time.',scaling:'Try sharing work and decisions before adding more customers.',leading:'Choose where your money and time help people and the business most.'}[state.stage];return `<section class="strategy-section"><div class="section-row"><h2>Your personal + business strategy.</h2><p>A simple plan for the next 90 days.<br>Choose it. Try it. Check what happened.</p></div><div class="strategy-thesis"><p class="eyebrow">YOUR SUGGESTED FOCUS / ${stage().name}</p><h3>${direction}</h3><p>Personal focus to explore: <strong>${personal.name}</strong>. Business focus to explore: <strong>${business.name}</strong>. These are areas your answers suggest checking. You can choose your own focus below.</p><p>${s.scores.some(d=>d.answered===d.total&&d.score!==null)?'Build from a strength: '+esc([...s.scores].filter(d=>d.answered===d.total).sort((a,b)=>b.score-a.score)[0].name)+' has your highest completed self-rating. Open its supporting record before reusing that working habit.':'Start with a strength you can demonstrate: name a habit, relationship or process that already works, then use it in your next experiment.'}</p></div><div class="strategy-grid">${C.domains.map(d=>{const v=saved[d.id]||{},prompts=strategicPrompts[state.stage][d.id];return `<section class="card"><div class="strategy-domain"><div class="domain-icon domain-${d.id}">${d.icon}</div><div><p class="eyebrow">${d.full}</p><h3>${d.name} strategy</h3></div></div><p class="strategy-suggestion"><strong>Suggested starting point:</strong> ${prompts[0]}</p>${[['goal','Name it','Open your records. Name the job, customer, activity or agreement you will work on.'],['measure','Evidence','Copy the dated entry, count, amount or actual words you found.'],['gap','Gap','Compare that record with the outcome or limit you chose. Write the difference.'],['cost','Cost','Use your records to write the time, money or relationship cost of leaving it as it is.'],['decision','Decision','Write what you will keep, stop or change, and the choice you are making.'],['experiment','Move','Open your calendar. Schedule the action, name the person and write what will be delivered.'],['review','Review','Book a review date. Name the record you will reopen and the result you will count.']].map(([key,label,placeholder])=>`<label>${label}<textarea data-strategy="${d.id}" data-strategy-key="${key}" maxlength="1500" placeholder="${placeholder}">${esc(v[key]||'')}</textarea></label>`).join('')}</section>`;}).join('')}</div><div class="notice">Bring the four parts together: help the right customers, make the money work, protect your time and build good working relationships. Choose what you will stop to make room for the plan. Check what you have learned after 30 days.</div></section>`;}
function report(){const s=C.summary(state),c=C.calculate(state.numbers,state.scenario,state.moneyRanges),p=C.patterns(state,c),acts=C.actions(state,c),check=checkpoint(c,s),hasAny=s.answered>0||C.fields.some(f=>state.numbers[f.key]!==''),strong=[...s.scores].filter(d=>d.answered===d.total).sort((a,b)=>b.score-a.score),index=C.stages.findIndex(x=>x.id===state.stage);return `${demoStrip()}<div class="intro no-print"><div><p class="eyebrow">LEVEL 03 / DELIBERATE ACTION</p><h1>Clarity is useful.<br><em>Your next move matters.</em></h1><p class="lede">Bring your answers and numbers together. Choose one small step that helps your business and your life.</p></div></div>${levels()}${journey()}<div class="print-only"><p>EXPLORASELF · LEADERSHIP COMPASS · ${new Date().toLocaleDateString('en-GB')}</p><p>${esc(state.profile.name)}${state.profile.business?' · '+esc(state.profile.business):''} · ${stage().name} · ${state.profile.currency}${state.demo?' · FICTIONAL EXAMPLE':''}</p></div><div class="report-head"><div><p class="eyebrow">${stage().name} / ${stage().role}</p><h2>${stage().focus}</h2><p>${hasAny?(check.covered?'Your answers cover this checklist. Choose the next stage to explore; this is not a readiness verdict.':'Stay curious about the gaps before your next commitment.'):'Your plan begins with a clear starting point. Enter responses and numbers to make this specific.'}</p></div><div class="actions"><button class="primary" data-print>Print / save PDF ↗</button><button class="secondary" style="color:var(--paper);border-color:var(--on-deep-line)" data-plan-download>Download plan</button></div></div>${!hasAny?'<div class="card empty no-print"><h3>There is no score to chase.</h3><p>Give this plan something real to work with: eight reflections for your stage and the business numbers you know.</p><div class="actions" style="justify-content:center"><a class="primary" href="#clarity">Begin the assessment →</a><a class="secondary" href="#method">How to use this</a></div></div>':''}${estimateNotice()}<div class="report-grid"><section class="card"><p class="eyebrow">THE FOUR-DOMAIN VIEW</p><h3>Your four-domain picture.</h3>${s.scores.map(d=>`<div class="evidence-item"><div class="domain-icon domain-${d.id}">${d.icon}</div><div><strong>${d.name} <span class="muted">· ${d.full}</span></strong><small>${d.answered}/2 responses · ${d.evidenced}/2 notes</small></div>${badge(d.answered===d.total?d.score+'% self-rating':'Incomplete',d.answered===d.total?'':'neutral')}</div>`).join('')}<p class="hint" style="margin-top:19px">${strong.length?strong[0].score!==null?esc(strong[0].name)+' has your highest completed self-rating. Open the record behind that answer before deciding what to reuse.':'Your completed responses point to foundations worth testing. There is no failure in naming a gap.':'Complete a domain to see its self-rating. Unknown responses are not scored as zero.'} Self-ratings measure your responses, not your competence or the value of your business.</p></section><section class="card"><p class="eyebrow">SEE YOUR NUMBERS</p><h3>The numbers behind the plan.</h3>${metric('Monthly money left after business costs',money(c.operating),'Simplified, before interest, tax and depreciation.')}${metric('After allowing for your unpaid time',money(c.economic),'Using the hourly value you chose for work without a wage.')}${metric('Money in minus money out',money(c.cashFlow),'Actual customer payments received minus all money paid out.')}${metric('How much of your available time you used',pct(c.capacity),'Compared with the hours you said you can comfortably work.')}<a class="text-button no-print" href="#numbers">Review all calculations and inputs →</a>${c.errors.length?'<p class="validation">'+c.errors.map(esc).join(' ')+'</p>':''}</section><section class="card"><p class="eyebrow">POSSIBLE BLIND SPOTS</p><h3>A different question to ask.</h3>${p.map(x=>`<div class="pattern"><h4>${esc(x.title)}</h4><p>${esc(x.why)}</p><p class="question-prompt">“${esc(x.ask)}”</p></div>`).join('')}<p class="hint">These are rule-based prompts. They do not establish a bias, a personality trait or a clinical diagnosis.</p></section><section class="card"><p class="eyebrow">NEXT STAGE TO EXPLORE</p><h3>${check.covered?'Choose the next stage to explore.':'Here is what still needs checking.'}</h3><ul class="stage-checks">${check.checks.map(x=>`<li>${x.ok?'✓':'○'} ${esc(x.text)}</li>`)}</ul><p class="hint" style="margin-top:15px">Check your real examples, whether sales cover delivery and selling costs, your cash goal and your work hours. These are conversation starters. You can explore any stage at any time.</p><details style="margin-top:15px"><summary style="font-size:11px;cursor:pointer">Records to open before the next step</summary><ul class="stage-checks">${stage().gates.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></details>${index<3?`<button class="secondary no-print" data-stage="${C.stages[index+1].id}" style="margin-top:17px">Explore ${C.stages[index+1].name.toLowerCase()} →</button>`:'<p class="hint" style="margin-top:17px">Leading is a continuing practice. Revisit all four domains whenever the context changes.</p>'}</section></div>${strategyCanvas(c,s)}<div class="section-row"><h2>Three practical next steps.</h2><p>Suggested sequence · adapt the pace<br>to your real constraints.</p></div><div class="plan-list">${acts.map((a,i)=>`<article class="card plan-step"><div class="n">0${i+1}</div><div><p class="task-meta">${['NEXT 48 HOURS','NEXT 7 DAYS','NEXT 30 DAYS'][i]} · ${C.domains.find(d=>d.id===a.domain)?.name.toUpperCase()||'WORK'}</p><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p><p style="margin-top:10px"><strong>Make it visible:</strong> ${esc(a.deliverable)}</p></div><div class="task-check"><label><input type="checkbox" data-done="${state.stage+'-'+a.key}" ${state.done[state.stage+'-'+a.key]?'checked':''}> I completed this step</label><p class="hint">Mark the action complete when you can show the result. Reassess after learning.</p></div></article>`).join('')}</div><section class="card" style="margin-top:24px"><p class="eyebrow">YOUR COMMITMENT</p><h3>Choose it. Name it. Review it.</h3><div class="reflection"><label>My first commitment<textarea data-note="commitment" maxlength="2000" placeholder="I will… by… so that…">${esc(state.notes.commitment||'')}</textarea></label><label>What I will stop or change<textarea data-note="stop" maxlength="2000" placeholder="To make room, I will stop…">${esc(state.notes.stop||'')}</textarea></label><label>Review date<input type="date" data-note="date" value="${esc(state.notes.date||'')}"></label><label>Evidence I will look for<textarea data-note="review" maxlength="2000" placeholder="I will know I have learned something when…">${esc(state.notes.review||'')}</textarea></label></div></section><section class="program-card no-print"><div><p class="eyebrow" style="color:var(--gold-hi)">CONTINUE WITH EXPLORASELF</p><h3>${s.scores.find(x=>x.id==='self').weak.length+s.scores.find(x=>x.id==='people').weak.length>=s.scores.find(x=>x.id==='work').weak.length+s.scores.find(x=>x.id==='market').weak.length?'Personal Leadership LAB':'Business Growth HUB'}</h3><p>${s.scores.find(x=>x.id==='self').weak.length+s.scores.find(x=>x.id==='people').weak.length>=s.scores.find(x=>x.id==='work').weak.length+s.scores.find(x=>x.id==='market').weak.length?'If your next move centres on purpose, boundaries or relationships, explore a deeper personal leadership conversation.':'If your next move centres on offers, economics or market evidence, explore the business side of personal leadership.'} Your plan is yours to use, whether independently or with support.</p></div><a class="secondary" href="https://exploraself.com" target="_blank" rel="noopener">Explore your options ↗</a></section><p class="hint" style="margin-top:20px">Planning aid only. Your inputs and assumptions need checking against your records. This report is not an audit, a business valuation, a professional qualification or a guarantee of outcomes. No financial, tax or legal advice is provided.</p>`;}
function method(){return `<div class="intro"><div><p class="eyebrow">THE EXPLORASELF APPROACH</p><h1>See the whole.<br><em>Choose the next step.</em></h1><p class="lede">A business decision changes your working life, your relationships, your systems and your place in the market. This compass makes those connections visible.</p></div></div><div class="method-grid"><section class="card"><p class="eyebrow">01 / FOUR DOMAINS</p><h3>Personal leadership meets business reality.</h3>${C.domains.map(d=>`<p style="margin-top:14px"><strong>${d.name} · ${d.full}</strong><br>${d.description} ${d.lens}</p>`).join('')}</section><section class="card"><p class="eyebrow">02 / FOUR STAGES</p><h3>From your first sale to helping others lead.</h3>${C.stages.map(s=>`<p style="margin-top:14px"><strong>${s.name} · ${s.role}</strong><br>${s.line}</p>`).join('')}<p style="margin-top:14px">These are useful contexts, not a hierarchy of personal worth. A small, sustainable business can be an intentional destination. You can be building one offer while leading another.</p></section><section class="card"><p class="eyebrow">03 / HOW THE ASSESSMENT WORKS</p><h3>Transparent by design.</h3><p>Each stage has eight reflections: two per domain. Responses carry 0, 1, 2 or 3 points. A domain self-rating appears only after both responses are answered: points ÷ 6 × 100, rounded. Unknown responses are not zero.</p><p style="margin-top:14px">Evidence notes count as added when you write something, but the tool cannot verify their quality. The checklist repeats your answers and notes; it does not certify readiness. These responses are your own record, not a validated test.</p><p style="margin-top:14px">A next-commitment checkpoint also asks for core numbers, positive contribution, a cash buffer at your chosen target and founder hours within your chosen capacity. It is a discussion aid. No stage is locked.</p><details><summary>How patterns and priorities are chosen</summary><p style="margin-top:12px">Prompts look for: positive surplus with a non-positive unpaid-time residual; profit with negative cash movement; hours above capacity; a completed business-domain response with costs not yet covered; a completed market-domain response with missing acquisition cost; one customer above 35% of revenue; or scaling/leading with founder dependency above 50%. Alex chose 35% customer share and 50% founder dependence as question prompts, not industry benchmarks. They never label a business ready, unsafe or worse than another founder.</p><p style="margin-top:12px">Actions prioritise conflicting inputs, then non-positive contribution, negative cash movement and capacity overload. Remaining actions come from the lowest-rated or unanswered reflections. No psychological diagnosis or causal claim is made.</p></details></section><section class="card"><p class="eyebrow">04 / FORMULAS & ASSUMPTIONS</p><h3>Every result has a definition.</h3><p>Choose a money range first, then type your own approximate amount. A range alone creates no calculated amount. The explicit zero choice uses zero. Approximate results carry “≈”. Switch to an exact amount when you have a record to copy. Existing exact inputs stay exact.</p><ul><li>Contribution = revenue − variable delivery costs − acquisition spending.</li><li>Left after business costs = contribution − shared operating costs.</li><li>Unpaid-time residual = operating surplus − unpaid founder hours × hourly value.</li><li>Sales needed to cover running costs = shared costs ÷ contribution margin, for positive margins only and an unchanged mix.</li><li>CAC = acquisition spending ÷ new paying customers.</li><li>Cash movement = actual collections − all cash payments.</li><li>How long your savings cover bills = available cash ÷ monthly payments.</li><li>Runway = cash ÷ net monthly burn, only if burn is positive.</li><li>Capacity use = total founder hours ÷ sustainable hours.</li></ul><p>Taxes, financing, depreciation, multi-period effects and offer-level variation require fuller models. Keep earned revenue separate from cash received.</p><details><summary>Primary reference material</summary><ul><li><a href="https://www.sba.gov/counseling/plan-your-business/break-even-point-calculator/" target="_blank" rel="noopener">U.S. Small Business Administration · Break-even</a></li><li><a href="https://www.sec.gov/about/reports-publications/beginners-guide-financial-statements" target="_blank" rel="noopener">U.S. SEC · Financial statements and cash flow</a></li><li><a href="https://business.gov.au/finance/cash-flow/set-up-a-cash-flow-statement" target="_blank" rel="noopener">business.gov.au · Cash-flow planning</a></li></ul><p>The ExploraSelf prompts, stage rules, action matching and scenario model are a proposed implementation for this tool. The sources do not validate those assessment rules.</p></details></section><section class="card"><p class="eyebrow">05 / YOUR DATA</p><h3>Your workspace stays with you.</h3><p>Assessment entries are stored in this browser’s local storage, not sent to an ExploraSelf server. Use Settings to restore or clear data; use the download arrow to keep a backup. Private browsing or clearing site data may remove your progress.</p><p style="margin-top:14px">The tool starts blank. Every calculated amount comes from your entries or an explicitly restored backup. The report can be printed or saved as a PDF using your browser, and downloaded as a text plan.</p></section><section class="card"><p class="eyebrow">06 / A HUMAN DECISION</p><h3>The point is a wiser next move.</h3><p>Use this tool to notice tensions, challenge assumptions and choose an experiment. It cannot decide what matters in your life, validate your records or certify that a business is ready to scale.</p><p style="margin-top:14px">Start where you are. A blank field, a changed mind or a smaller ambition can each be a useful answer.</p><a class="primary" href="#clarity" style="margin-top:22px">Find my starting point →</a></section></div>`;}
function render(){const theme=state.profile.theme||'system';if(theme==='system')document.documentElement.removeAttribute('data-theme');else document.documentElement.dataset.theme=theme;page=location.hash.slice(1)||'overview';if(!['overview','clarity','numbers','plan','method'].includes(page))page='overview';$('#main').innerHTML=({overview,clarity,numbers,plan:report,method})[page]();document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#nav-count').textContent=C.summary(state).answered+'/8';document.title=({overview:'Your compass',clarity:'Find your clarity',numbers:'Know your numbers',plan:'Strategy & next moves',method:'How it works'})[page]+' · ExploraSelf';}
function enterDemo(){location.hash='method';}
function exitDemo(){state.demo=false;save();render();}
function planText(){const s=C.summary(state),c=C.calculate(state.numbers,state.scenario,state.moneyRanges),checks=checkpoint(c,s),acts=C.actions(state,c);return ['EXPLORASELF · LEADERSHIP COMPASS',new Date().toLocaleDateString('en-GB'),[state.profile.name,state.profile.business].filter(Boolean).join(' · '),state.demo?'FICTIONAL EXAMPLE':'PERSONAL WORKSPACE','Stage: '+stage().name+' · '+stage().role,'Currency: '+state.profile.currency,...(C.estimatedKeys(state).length?['APPROXIMATE AMOUNTS: every amount was entered by the visitor. Ranges never supply a midpoint. Review estimates against your records.']:[]),'',stage().focus,'','FOUR DOMAINS',...s.scores.map(d=>d.name+': '+(d.answered===d.total?d.score+'% self-rating':'Incomplete')+'; '+d.answered+'/2 responses, '+d.evidenced+'/2 notes.'),'','SEE YOUR NUMBERS','Left after business costs: '+money(c.operating),'After allowing for your unpaid time: '+money(c.economic),'Money in minus money out: '+money(c.cashFlow),'How long your savings cover bills: '+decimal(c.buffer,' months'),'Your work hours versus your limit: '+pct(c.capacity),'',...c.errors,'','POSSIBLE BLIND SPOTS',...C.patterns(state,c).flatMap(p=>[p.title,p.why,p.ask,'']),'WHAT TO CHECK NEXT',...checks.checks.map(x=>(x.ok?'[x] ':'[ ] ')+x.text),'','PERSONAL + BUSINESS STRATEGY',...C.domains.flatMap(d=>{const v=state.strategy[state.stage]?.[d.id]||{};return [d.name+' · '+d.full,...['goal','measure','gap','cost','decision','experiment','review'].map((k,i)=>['Name it','Evidence','Gap','Cost','Decision','Move','Review'][i]+': '+(v[k]||'Not yet written')),''];}),'NEXT MOVES',...acts.flatMap((a,i)=>[(i+1)+'. '+a.title,a.text,'Visible outcome: '+a.deliverable,'Complete: '+(state.done[state.stage+'-'+a.key]?'Yes':'Not yet'),'']),'MY FIRST STEP',state.notes.commitment||'Not yet chosen','What I will stop or change: '+(state.notes.stop||'Not yet chosen'),'Review date: '+(state.notes.date||'Not yet chosen'),'Evidence to look for: '+(state.notes.review||'Not yet chosen'),'','INPUTS & DEFINITIONS',...C.fields.map(f=>f.label+': '+(state.moneyRanges?.[f.key]&&state.moneyRanges[f.key]!=='exact'?bandLabel(C.bandsFor(f.key).find(b=>b.id===state.moneyRanges[f.key]))+'; calculation uses '+(state.numbers[f.key]===''?'unknown':state.numbers[f.key]):state.numbers[f.key]===''?'Unknown':state.numbers[f.key])+' ('+f.unit+')'),'Data limitations: '+(state.notes.data||'Not recorded'),'','ASSESSMENT EVIDENCE',...s.questions.flatMap(q=>[q.text,'Response: '+(Number.isInteger(state.answers[q.id])?answerLabels[state.answers[q.id]][0]:'Unknown'),'Note: '+(state.evidence[q.id]||'None'),'']),'Self-reported reflection and simplified planning only. This is not a validated readiness test, an audit or professional financial advice. Positive contribution, your chosen cash target and capacity limit are proposed discussion criteria, not universal benchmarks. Approximate amounts are those you entered within your chosen ranges. All sources and formulas are available in How it works.'].join('\n');}
function askStage(to,answered){const from=stage(),next=C.stages.find(x=>x.id===to);let d=document.getElementById('stage-dialog');
 if(!d){d=document.createElement('dialog');d.id='stage-dialog';document.body.appendChild(d);}
 d.innerHTML=`<p class="eyebrow">ONE STAGE AT A TIME</p><h2>You chose ${esc(from.name)}.</h2><p>Your summary uses the eight answers for one stage only, so it stays true to where you are. You have answered ${answered} for ${esc(from.name)}.</p><p><b>Change to ${esc(next.name)}?</b> Your ${esc(from.name)} answers are kept if you come back.</p><div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:18px"><button class="primary" id="stage-yes">Yes, change to ${esc(next.name)}</button><button class="secondary" id="stage-no">Stay with ${esc(from.name)}</button></div>`;
 d.querySelector('#stage-yes').onclick=()=>{d.close();state.stage=to;save();render();toast(next.name+' selected.');};
 d.querySelector('#stage-no').onclick=()=>d.close();d.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,label');if(!b)return;
 if(b.dataset.stage){const to=b.dataset.stage;if(to===state.stage)return;
  // One stage at a time: the summary reads only the chosen stage's eight answers.
  const answered=C.Q.filter(q=>q.stage===state.stage&&Number.isInteger(state.answers[q.id])).length;
  if(answered){askStage(to,answered);return;}
  state.stage=to;save();render();toast(stage().name+' selected.');}
 if(b.dataset.domain){domain=b.dataset.domain;if(page==='clarity'){e.preventDefault();render();}}
 if(b.hasAttribute('data-answer')){state.answers[b.dataset.answer]=Number(b.dataset.value);save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-answer="${b.dataset.answer}"][data-value="${b.dataset.value}"]`)?.focus({preventScroll:true});}
 if(b.hasAttribute('data-next-domain')||b.hasAttribute('data-prev-domain')){domain=C.domains[C.domains.findIndex(d=>d.id===domain)+(b.hasAttribute('data-next-domain')?1:-1)].id;render();$('#main').scrollIntoView({block:'start'});}
 if(b.hasAttribute('data-demo'))enterDemo();if(b.hasAttribute('data-exit-demo'))exitDemo();if(b.hasAttribute('data-print'))window.print();if(b.hasAttribute('data-plan-download'))download('ExploraSelf-Leadership-Plan.txt',planText());
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.number){state.numbers[el.dataset.number]=el.value===''?'':Number(el.value);if(el.value!==''&&state.legacyAmounts){delete state.legacyAmounts[el.dataset.number];state.needsAmountReview=Object.keys(state.legacyAmounts).length>0;}save();updateNumberResults();}if(el.dataset.scenario){state.scenario[el.dataset.scenario]=Number(el.value);$('#o-'+el.dataset.scenario).textContent=(Number(el.value)>0?'+':'')+el.value+'%';save();$('#scenario-results').innerHTML=scenarioResults();}if(el.dataset.strategy){const st=state.strategy[state.stage]||(state.strategy[state.stage]={});const d=st[el.dataset.strategy]||(st[el.dataset.strategy]={});d[el.dataset.strategyKey]=el.value;save();}if(el.dataset.evidence){state.evidence[el.dataset.evidence]=el.value;save();}if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();}});
function updateNumberResults(){$('#number-results').innerHTML=numberResults();$('#scenario-results').innerHTML=scenarioResults();$('#scenario-estimates').innerHTML=estimateNotice();}
document.addEventListener('change',e=>{if(e.target.dataset.moneyRange){const key=e.target.dataset.moneyRange;C.applyMoneyChoice(state,key,e.target.value);save();const f=C.fields.find(f=>f.key===key);$('#field-'+key).innerHTML=rangeFieldInner(f);updateNumberResults();$('#r-'+key).focus();}if(e.target.dataset.done){state.done[e.target.dataset.done]=e.target.checked;save();}});
$('#demo').addEventListener('click',enterDemo);$('#export').addEventListener('click',()=>download('ExploraSelf-Compass-Backup.json',JSON.stringify(state,null,2),'application/json'));
$('#settings').addEventListener('click',()=>{for(const key of ['name','business','type','currency','theme'])$('#profile-'+key).value=state.profile[key];$('#settings-dialog').showModal();});
$('#save-settings').addEventListener('click',()=>{for(const key of ['name','business','type','currency','theme'])state.profile[key]=$('#profile-'+key).value.trim();save();$('#settings-dialog').close();render();toast('Preferences saved. Currency labels do not convert amounts.');});
$('#reset').addEventListener('click',()=>{if(confirm('Clear all assessment answers, business inputs and notes in this workspace? Download a backup first if you want to keep them.')){state=C.blank();try{localStorage.removeItem(BEFORE_DEMO);window.priorState=null;}catch(_){}save();$('#settings-dialog').close();render();toast('Your workspace has been cleared.');}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>200000)throw Error('Please choose a Compass backup smaller than 200 KB.');const next=C.sanitize(JSON.parse(await f.text()));if(!confirm('Replace the current workspace with this backup?'))return;state=next;save();$('#settings-dialog').close();render();toast('Your backup has been restored.');}catch(err){toast(err.message||'This backup could not be read.');}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
